// Provided for lab 12.3. You do not edit this file (CUDA; also built for HIP and for the CPU
// emulators).
//
// An exclusive scan of 32-bit unsigned integers, built the way section 11.9 builds a global
// scan out of block scans (scan-scan-add, Fig. 11.14, pp. 273-274): every block scans one tile
// and writes the tile's total; the totals are scanned the same way (recursively, so any n
// works); a last kernel adds to every element the sum of all tiles before its own. No block
// ever waits for another block, so nothing here needs a forward-progress guarantee and it runs
// on every backend (notes/today/ch12-facts.md A10, B6, C4).
//
//   unsigned int scanScratchElems(unsigned int n)
//       elements of scratch memory launchExclusiveScanU32 needs for n inputs (at least 1).
//   void launchExclusiveScanU32(const unsigned int* in, unsigned int* out, unsigned int n,
//                               unsigned int* scratch)
//       out[0] = 0, out[i] = in[0] + ... + in[i-1]. n >= 1. in == out is allowed. The sum of
//       all n inputs must fit in 32 bits. scratch holds scanScratchElems(n) elements.
//   void launchCopyU32(const unsigned int* in, unsigned int* out, unsigned int n)
//       out[i] = in[i]: the benchmark's reference for what moving 8 bytes per key costs.
//
// Traffic: the block scans read n and write n elements, the add reads n and writes n, so
// 16 bytes per element plus about 8/1024 for the tile totals (the book's count, p. 274).
//
// Inside a block (Figs. 11.12 and 11.13): a coalesced load of the tile into shared memory,
// a sequential scan of each thread's SCAN_ITEMS consecutive elements, a Kogge-Stone scan of
// the thread totals in shared memory, and a coalesced store. The Kogge-Stone step uses only
// shared memory and barriers, so this file has no warp intrinsics and no lane masks.
#define SCAN_BLOCK_DIM 256
#define SCAN_ITEMS 4
#define SCAN_TILE (SCAN_BLOCK_DIM * SCAN_ITEMS)

// Scans each tile of SCAN_TILE elements on its own. tileTotals may be null (single tile).
__global__ void scanTilesU32Kernel(const unsigned int* in, unsigned int* out, unsigned int n,
                                   unsigned int* tileTotals) {
    __shared__ unsigned int tile_s[SCAN_TILE];
    __shared__ unsigned int sums_s[2][SCAN_BLOCK_DIM];

    const unsigned int t = threadIdx.x;
    const unsigned int base = blockIdx.x * SCAN_TILE;

    // Coalesced load: element c * SCAN_BLOCK_DIM + t of the tile. Past the end: 0.
    for (unsigned int c = 0; c < SCAN_ITEMS; ++c) {
        const unsigned int i = base + c * SCAN_BLOCK_DIM + t;
        tile_s[c * SCAN_BLOCK_DIM + t] = i < n ? in[i] : 0u;
    }
    __syncthreads();   // every element of the tile is in shared memory (in == out is safe from here)

    // Sequential exclusive scan of this thread's SCAN_ITEMS consecutive elements.
    unsigned int local[SCAN_ITEMS];
    unsigned int threadSum = 0;
    for (unsigned int c = 0; c < SCAN_ITEMS; ++c) {
        local[c] = threadSum;
        threadSum += tile_s[t * SCAN_ITEMS + c];
    }

    // Kogge-Stone inclusive scan of the thread totals, double-buffered as in Fig. 11.5
    // (section 11.3): one barrier per step.
    unsigned int src = 0;
    sums_s[src][t] = threadSum;
    __syncthreads();
    for (unsigned int stride = 1; stride < SCAN_BLOCK_DIM; stride *= 2) {
        unsigned int v = sums_s[src][t];
        if (t >= stride) {
            v += sums_s[src][t - stride];
        }
        sums_s[1 - src][t] = v;
        src = 1 - src;
        __syncthreads();
    }
    const unsigned int inclusive = sums_s[src][t];
    const unsigned int before = inclusive - threadSum;   // the totals of threads 0 .. t-1

    for (unsigned int c = 0; c < SCAN_ITEMS; ++c) {
        tile_s[t * SCAN_ITEMS + c] = local[c] + before;
    }
    if (tileTotals != nullptr && t == SCAN_BLOCK_DIM - 1) {
        tileTotals[blockIdx.x] = inclusive;   // the last thread's inclusive value is the tile's total
    }
    __syncthreads();

    for (unsigned int c = 0; c < SCAN_ITEMS; ++c) {
        const unsigned int i = base + c * SCAN_BLOCK_DIM + t;
        if (i < n) {
            out[i] = tile_s[c * SCAN_BLOCK_DIM + t];
        }
    }
}

// Adds the scanned tile totals: out[i] += tileOffsets[tile of i].
__global__ void addTileOffsetsU32Kernel(unsigned int* out, unsigned int n, const unsigned int* tileOffsets) {
    const unsigned int add = tileOffsets[blockIdx.x];
    const unsigned int base = blockIdx.x * SCAN_TILE;
    for (unsigned int c = 0; c < SCAN_ITEMS; ++c) {
        const unsigned int i = base + c * SCAN_BLOCK_DIM + threadIdx.x;
        if (i < n) {
            out[i] += add;
        }
    }
}

__global__ void copyU32Kernel(const unsigned int* in, unsigned int* out, unsigned int n) {
    const unsigned int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) {
        out[i] = in[i];
    }
}

static unsigned int scanCeilDiv(unsigned int a, unsigned int b) { return (a + b - 1) / b; }

// One level of tile totals per level of the recursion, each rounded up to 4 elements.
unsigned int scanScratchElems(unsigned int n) {
    unsigned int total = 0;
    while (n > SCAN_TILE) {
        n = scanCeilDiv(n, SCAN_TILE);
        total += (n + 3) / 4 * 4;
    }
    return total > 0 ? total : 1;
}

void launchExclusiveScanU32(const unsigned int* in, unsigned int* out, unsigned int n, unsigned int* scratch) {
    if (n == 0) {
        return;
    }
    const unsigned int tiles = scanCeilDiv(n, SCAN_TILE);
    if (tiles == 1) {
        scanTilesU32Kernel<<<1, SCAN_BLOCK_DIM>>>(in, out, n, nullptr);
        return;
    }
    unsigned int* totals = scratch;                        // this level's tile totals
    unsigned int* rest = scratch + (tiles + 3) / 4 * 4;    // scratch for the levels above
    scanTilesU32Kernel<<<tiles, SCAN_BLOCK_DIM>>>(in, out, n, totals);
    launchExclusiveScanU32(totals, totals, tiles, rest);   // in place: totals -> tile offsets
    addTileOffsetsU32Kernel<<<tiles, SCAN_BLOCK_DIM>>>(out, n, totals);
}

void launchCopyU32(const unsigned int* in, unsigned int* out, unsigned int n) {
    if (n == 0) {
        return;
    }
    copyU32Kernel<<<scanCeilDiv(n, 256), 256>>>(in, out, n);
}
